import{_ as a}from"./chunks/reg_vector_overview.DFZawUoG.js";import{_ as n,o as p,a as c,b as l}from"./app.ejsEy6QV.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"Reg矢量计算","link":"/api/SIMD-API/c_api/reg_compute/reg_compute"},{"text":"概述","link":"/api/SIMD-API/c_api/reg_compute/overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/reg_compute/overview.md","filePath":"api/SIMD-API/c_api/reg_compute/overview.md","outlineHeaders":[{"level":2,"title":"如何使用Reg矢量计算API","slug":"如何使用Reg矢量计算API","link":"#如何使用Reg矢量计算API"},{"level":2,"title":"Reg矢量计算编程示例","slug":"Reg矢量计算编程示例","link":"#Reg矢量计算编程示例"},{"level":2,"title":"通用约束","slug":"通用约束","link":"#通用约束"}],"lastUpdated":1789723795000}'),e={name:"api/SIMD-API/c_api/reg_compute/overview.md"};function _(t,s,o,i,r,d){return p(),c("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>概述</h1><p>Reg矢量计算C API提供面向Reg矢量计算架构的寄存器级矢量计算能力，用户可以通过该API直接对芯片中涉及Vector计算的寄存器进行操作，实现更大的灵活性和更好的性能。Reg矢量计算C API与Memory矢量计算C API功能相似，但与Memory矢量计算C API的输入和输出数据通常位于Unified Buffer（UB）不同，Reg矢量计算C API的输入或输出数据可使用矢量数据寄存器<code>vector_&lt;dtype&gt;</code>（<code>dtype</code>为占位符，表示<code>half</code>、<code>float</code>等C API支持的数据类型）和掩码寄存器<code>vector_bool</code>。对于计算类API，其功能是从给定的寄存器获取数据，进行计算，并将结果保存在给定的寄存器。对于搬运类API，其功能是实现UB和寄存器的数据搬运。由此可见，Reg矢量计算C API相较于Memory矢量计算C API，将数据搬运和Reg计算过程交给用户自主控制，从而实现更大的开发自由度。</p><h2 id="如何使用Reg矢量计算API">如何使用Reg矢量计算API<a class="header-anchor" href="#如何使用Reg矢量计算API">​</a></h2><p>基于寄存器的编程模型是指将数据从UB通过Reg搬运指令（Reg数据搬入）加载到寄存器中，进行复杂的数学计算后通过Reg搬运指令（Reg数据搬出）搬出到UB中，所有的计算逻辑均在寄存器中完成，从而减少UB中间数据的反复读写，大大提升整体性能，具体流程如下所示：</p><p><strong>图1</strong> Reg矢量计算</p><p><img src="'+a+`" alt title="Reg矢量计算"></p><p>以<a href="#reg%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97%E7%BC%96%E7%A8%8B%E7%A4%BA%E4%BE%8B">Reg矢量计算编程示例</a>为例，完整的Vector Function计算过程由以下几部分组成：</p><ul><li>编写和调用Vector Function（向量函数）。这些函数使用<code>__simd_vf__</code>标记，可在核函数（Kernel）中调用；</li><li>定义矢量数据寄存器<code>vector_&lt;dtype&gt;</code>、掩码寄存器<code>vector_bool</code>，更多Reg数据类型请参见<a href="../defs/type/data_type_definition.html">Reg数据类型定义</a>；</li><li>编写循环处理多个VL长度的数据；<a href="./reg_mask/asc_update_mask.html">asc_update_mask</a>系列接口用于更新参与计算的mask，每次循环都会消耗一个VL长度的元素；</li><li>循环内调用Reg数据搬入接口连续对齐搬入（<a href="./load/asc_loadalign.html">asc_loadalign</a>）从UB中搬入单个VL长度数据；</li><li>循环内调用Reg计算接口<a href="./reg_arith/asc_add.html">asc_add</a>完成单次Repeat计算；</li><li>循环内调用Reg数据搬出接口连续对齐搬出（<a href="./store/asc_storealign.html">asc_storealign</a>）往UB中搬出计算后的数据。</li></ul><h2 id="Reg矢量计算编程示例">Reg矢量计算编程示例<a class="header-anchor" href="#Reg矢量计算编程示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>

<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src1</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_float</span><span class="w"> </span><span class="n">dst_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_float</span><span class="w"> </span><span class="n">src0_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_float</span><span class="w"> </span><span class="n">src1_reg</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b32</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">src0_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">src1_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_add</span><span class="p">(</span><span class="n">dst_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src0_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">dst_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="p">}</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_add_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src1</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_init</span><span class="p">();</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">dst_local</span><span class="p">[</span><span class="n">ELEMENT_COUNT</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">src0_local</span><span class="p">[</span><span class="n">ELEMENT_COUNT</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">src1_local</span><span class="p">[</span><span class="n">ELEMENT_COUNT</span><span class="p">];</span>

<span class="w">    </span><span class="c1">// GM数据搬运至UB地址src0_local及src1_local</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">src0_local</span><span class="p">,</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">src1_local</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 调用vf函数</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">add_vf</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dst_local</span><span class="p">,</span><span class="w"> </span><span class="n">src0_local</span><span class="p">,</span><span class="w"> </span><span class="n">src1_local</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// UB地址dst_local数据搬运至GM</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">dst_local</span><span class="p">,</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_sync</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>GM与UB间的数据搬运需通过C API数据搬运接口完成；</li><li>Vector Function的流水类型为PIPE_V，Vector Function内部如存在UB地址重叠或跨流水依赖，需要根据具体接口约束插入<a href="./reg_sync/asc_mem_bar.html">asc_mem_bar</a>。</li></ul></div><h2 id="通用约束">通用约束<a class="header-anchor" href="#通用约束">​</a></h2><ul><li>通过引用参数输出结果的Reg矢量计算C API，在非AIV上调用时直接返回。</li><li>通过函数返回值输出结果的Reg矢量计算C API，在非AIV上调用时返回对应矢量类型的默认构造值。</li><li>Reg矢量计算C API接口需要在Vector Function（<code>__simd_vf__</code> 标记的函数）内调用，不支持在<code>__aicore__</code>函数中直接调用，调用关系请参考<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">SIMD BuiltIn关键字</a>。</li><li>对于支持配置<code>mask</code>参数的Reg矢量计算C API接口，<code>mask</code>需通过<a href="./reg_mask/reg_mask.html">掩码设置接口</a>预先赋值后再传入，未赋值的掩码寄存器内容不确定，会导致有效元素位置错误。</li></ul></article></div>`,1)])])}const m=n(e,[["render",_]]);export{h as __pageData,m as default};
